function a(t){if(t<1024)return`${t} B`;const n=["KB","MB","GB"];let r=t/1024,e=0;for(;r>=1024&&e<n.length-1;)r/=1024,e+=1;return`${r.toFixed(r>=10?0:1)} ${n[e]}`}function i(t){return`${Math.round(t*100)}%`}function o(t){if(!t)return"-";const n=new Date(t);return Number.isNaN(n.getTime())?t:`${String(n.getMonth()+1).padStart(2,"0")}-${String(n.getDate()).padStart(2,"0")} ${String(n.getHours()).padStart(2,"0")}:${String(n.getMinutes()).padStart(2,"0")}`}export{a,o as b,i as f};
